"""Terminal helpers. # spec: FP-11 (N-000608..N-000676), Contract 7 (N-000963..N-000982)"""

import contextlib
import io
import os
import re
import subprocess
import sys
import tempfile
import time

from .exceptions import Abort

_ANSI_RE = re.compile(r"\x1b\[[0-9;?]*[ -/]*[@-~]")

_COLORS = {
    "black": 30, "red": 31, "green": 32, "yellow": 33,
    "blue": 34, "magenta": 35, "cyan": 36, "white": 37,
    "bright_black": 90, "bright_red": 91, "bright_green": 92, "bright_yellow": 93,
    "bright_blue": 94, "bright_magenta": 95, "bright_cyan": 96, "bright_white": 97,
    "reset": 39,
}

_SWITCHES = [
    ("bold", 1, 22), ("dim", 2, 22), ("underline", 4, 24), ("overline", 53, 55),
    ("italic", 3, 23), ("blink", 5, 25), ("reverse", 7, 27), ("strikethrough", 9, 29),
]


def _color_code(color, base):
    """Return SGR parameter string for a color. # spec: N-000618..N-000630"""
    if isinstance(color, str):
        if color not in _COLORS:
            raise TypeError(f"unknown color {color!r}")
        code = _COLORS[color]
        if color == "reset":
            return "0"
        return str(code + (10 if base == "bg" else 0))
    if isinstance(color, int) and not isinstance(color, bool):
        if not 0 <= color <= 255:
            raise TypeError(f"color index {color} out of range")
        return f"{48 if base == 'bg' else 38};5;{color}"
    if isinstance(color, (tuple, list)) and len(color) == 3 and all(
        isinstance(c, int) and 0 <= c <= 255 for c in color
    ):
        return f"{48 if base == 'bg' else 38};2;{color[0]};{color[1]};{color[2]}"
    raise TypeError(f"invalid color {color!r}")


def style(text, fg=None, bg=None, bold=None, dim=None, underline=None, overline=None,
          italic=None, blink=None, reverse=None, strikethrough=None, reset=True):
    """Wrap text in ANSI SGR sequences. # spec: N-000618..N-000630"""
    bits = []
    if fg is not None:
        bits.append(_color_code(fg, "fg"))
    if bg is not None:
        bits.append(_color_code(bg, "bg"))
    flags = dict(bold=bold, dim=dim, underline=underline, overline=overline,
                 italic=italic, blink=blink, reverse=reverse, strikethrough=strikethrough)
    for name, on, off in _SWITCHES:
        if flags[name] is not None:
            bits.append(str(on if flags[name] else off))
    if not bits:
        return str(text)
    prefix = f"\x1b[{';'.join(bits)}m"
    end = "\x1b[0m" if reset else ""
    return f"{prefix}{text}{end}"


def unstyle(text):
    """Remove ANSI sequences. # spec: N-000630"""
    return _ANSI_RE.sub("", str(text))


def _stream_is_tty(stream):
    try:
        return bool(stream.isatty())
    except Exception:
        return False


def _should_strip(stream, color):
    if color is True:
        return False
    if color is False:
        return True
    return not _stream_is_tty(stream)


