    try:
        stream.write(text)
    except UnicodeEncodeError:
        # ASCII-only encodings: fall back to UTF-8 bytes. # spec: N-000609
        buf = getattr(stream, "buffer", None)
        if buf is not None:
            buf.write(text.encode("utf-8"))
            buf.flush()
        else:
            stream.write(text.encode("utf-8", "replace").decode("ascii", "replace"))


def _current_color():
    from .core import get_current_context

    ctx = get_current_context(silent=True)
    return None if ctx is None else ctx.color


def echo(message=None, file=None, nl=True, err=False, color=None):
    """Write text or bytes. # spec: N-000609..N-000617"""
    if file is None:
        file = sys.stderr if err else sys.stdout
    if message is None:
        message = ""
    if isinstance(message, bytes):
        buf = getattr(file, "buffer", None)
        if buf is not None:
            buf.write(message + (b"\n" if nl else b""))
            buf.flush()
        else:
            file.write(message.decode("utf-8", "replace") + ("\n" if nl else ""))
        return
    if color is None:
        color = _current_color()
    text = str(message)
    if _should_strip(file, color):
        text = unstyle(text)
    if nl:
        text += "\n"
    _write(file, text)
    try:
        file.flush()
    except Exception:
        pass


def secho(message=None, file=None, nl=True, err=False, color=None, **styles):
    """Echo styled text. # spec: N-000618"""
    if message is not None:
        message = style(message, **styles)
    return echo(message, file=file, nl=nl, err=err, color=color)


