           value_proc=None, prompt_suffix=": ", show_default=True, err=False):
    """Ask for a value. Re-asks on conversion failure. # spec: FP-08 (N-000491..N-000512)"""
    from .types import STRING, _as_type

    ptype = STRING if type is None else _as_type(type)
    while True:
        shown = text
        if default is not None and show_default:
            shown += f" [{default}]"
        echo(shown + prompt_suffix, nl=False, err=err)
        value = _read_line(hide_input)
        if value == "" and default is not None:
            value = default
        if confirmation_prompt:
            echo("Repeat for confirmation" + prompt_suffix, nl=False, err=err)
            second = _read_line(hide_input)
            if second != value:
                echo("Error: the two entered values do not match", err=True)
                continue
        try:
            return ptype(value)
        except Exception as exc:
            echo(f"Error: {getattr(exc, 'message', exc)}", err=True)


def _read_line(hide_input=False):
    from . import testing as _testing  # noqa: F401  (runner may replace stdin)

    line = sys.stdin.readline()
    if line == "":
        raise Abort()
    return line.rstrip("\r\n")


def confirm(text, default=False, abort=False, prompt_suffix=": ", show_default=True,
            err=False):
    """Yes/no question. # spec: FP-08 (N-000491..N-000499), N-001016"""
    suffix = " [Y/n]: " if default else " [y/N]: "
    while True:
        echo(text + suffix, nl=False, err=err)
        line = sys.stdin.readline()
        if line == "":
            raise Abort()
        answer = line.strip().lower()
        if answer == "":
            value = default
        elif answer in ("y", "yes"):
            value = True
        else:
            value = False
        break
    if not value and abort:
        raise Abort()
    return value


def getchar(echo=False):
    """Read one character. # spec: N-000648..N-000651"""
    try:
        import termios
        import tty
    except ImportError:  # pragma: no cover
        ch = sys.stdin.read(1)
    else:
        fd = sys.stdin.fileno()
        old = termios.tcgetattr(fd)
        try:
            tty.setraw(fd)
            ch = os.read(fd, 1).decode("utf-8", "replace")
        finally:
            termios.tcsetattr(fd, termios.TCSADRAIN, old)
