        echo(ch, nl=False)
    return ch


def pause(info=None, err=False):
    """Wait for a key when interactive. # spec: N-000652, N-000675"""
    if not (_stream_is_tty(sys.stdin) and _stream_is_tty(sys.stdout)):
        return
    echo(info or "Press any key to continue...", err=err, nl=False)
    try:
        getchar()
    except (KeyboardInterrupt, EOFError):
        pass
    echo("", err=err)


def clear():
    """Clear the screen when on a terminal. # spec: N-000662"""
    if not _stream_is_tty(sys.stdout):
        return
    sys.stdout.write("\033[2J\033[H")
    sys.stdout.flush()


def echo_via_pager(text_or_generator, color=None):
    """Write text through $PAGER when interactive. # spec: N-000631..N-000638"""
    if callable(text_or_generator):
        text_or_generator = text_or_generator()
    if isinstance(text_or_generator, str):
        chunks = [text_or_generator]
    else:
        chunks = text_or_generator
    interactive = _stream_is_tty(sys.stdin) and _stream_is_tty(sys.stdout)
    pager = os.environ.get("PAGER")
    if not interactive or not pager:
        for chunk in chunks:
            echo(chunk, nl=False, color=color)
        return
    proc = subprocess.Popen(pager, shell=True, stdin=subprocess.PIPE)
    try:
        for chunk in chunks:
            proc.stdin.write(str(chunk).encode("utf-8"))
            proc.stdin.flush()
    except BrokenPipeError:
        pass
    finally:
        try:
            proc.stdin.close()
        except Exception:
            pass
        proc.wait()


@contextlib.contextmanager
def get_pager_file(color=None):
    """Yield a writable text stream for pager output. # spec: N-000631"""
    buf = io.StringIO()
    yield buf
    echo_via_pager(buf.getvalue(), color=color)


class ProgressBar:
    """Iterable progress bar. # spec: N-000639..N-000647"""

    def __init__(self, iterable=None, length=None, label=None, hidden=False, **options):
        self.iterable = iterable
        self.length = length if length is not None else (
            len(iterable) if iterable is not None and hasattr(iterable, "__len__") else None
        )
        self.label = label
        self.hidden = hidden
        self.pos = 0
        self.start = time.time()
        self.options = options
        self.tty = (not hidden) and _stream_is_tty(sys.stdout)
        if not self.tty and not hidden and label:
            echo(label)

    def __iter__(self):
        if self.iterable is None:
            return
        for item in self.iterable:
            yield item
            self.update(1)
        self._finish()

    def update(self, n_steps):
        self.pos += n_steps
        if self.tty:
            if self.length:
                pct = min(self.pos / self.length, 1.0)
                filled = int(pct * 30)
                elapsed = time.time() - self.start
                eta = (elapsed / pct - elapsed) if pct > 0 else 0
                bar = "#" * filled + "-" * (30 - filled)
                sys.stdout.write(f"\r{self.label or ''} [{bar}] {self.pos}/{self.length} eta {int(eta)}s")
