    def __init__(self, iterable=None, length=None, label=None, hidden=False, **options):
        self.iterable = iterable
        self.length = length if length is not None else (
            len(iterable) if iterable is not None and hasattr(iterable, "__len__") else None
        )
        self.label = label
        self.hidden = hidden
        self.pos = 0
        self.start = time.time()
        self.options = options
        self.tty = (not hidden) and _stream_is_tty(sys.stdout)
        if not self.tty and not hidden and label:
            echo(label)

    def __iter__(self):
        if self.iterable is None:
            return
        for item in self.iterable:
            yield item
            self.update(1)
        self._finish()

    def update(self, n_steps):
        self.pos += n_steps
        if self.tty:
            if self.length:
                pct = min(self.pos / self.length, 1.0)
                filled = int(pct * 30)
                elapsed = time.time() - self.start
                eta = (elapsed / pct - elapsed) if pct > 0 else 0
                bar = "#" * filled + "-" * (30 - filled)
                sys.stdout.write(f"\r{self.label or ''} [{bar}] {self.pos}/{self.length} eta {int(eta)}s")
            else:
                sys.stdout.write(f"\r{self.label or ''} {self.pos}")
            sys.stdout.flush()

