        subprocess.call(editor.split() + [str(filename)], env=env)
        return None
    fd, path = tempfile.mkstemp(suffix=extension)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write(text or "")
        mtime = os.path.getmtime(path)
        subprocess.call(editor.split() + [path], env=env)
        with open(path, encoding="utf-8") as f:
            result = f.read()
        if require_save and os.path.getmtime(path) == mtime and text is not None:
