        self.terminal_width = settings.get("terminal_width")
        self.max_content_width = settings.get("max_content_width", self.DEFAULT_MAX_CONTENT_WIDTH)
        self.help_option_names = list(settings.get("help_option_names", ["--help"]))
        self.token_normalize_func = settings.get("token_normalize_func")
        self.color = settings.get("color")
