        self.parent = parent
        self.info_name = info_name or (command.name if command is not None else None)
        settings = dict(settings or {})
        if parent is not None:
            inherited = dict(parent.settings)
            inherited.update(settings)
            settings = inherited
        self.settings = settings
        self.obj = obj if obj is not None else (parent.obj if parent is not None else None)
        self.default_map = default_map
        self.params = {}
        self.args = []
        self.protected_args = []
        self.invoked_subcommand = None
        self.auto_envvar_prefix = settings.get("auto_envvar_prefix")
        self.terminal_width = settings.get("terminal_width")
        self.max_content_width = settings.get("max_content_width", self.DEFAULT_MAX_CONTENT_WIDTH)
        self.help_option_names = list(settings.get("help_option_names", ["--help"]))
        self.token_normalize_func = settings.get("token_normalize_func")
        self.color = settings.get("color")
        self.show_default = settings.get("show_default")
        self.allow_extra_args = settings.get("allow_extra_args", command.allow_extra_args if command else False)
        self.ignore_unknown_options = settings.get("ignore_unknown_options", False)
        self.allow_interspersed_args = settings.get("allow_interspersed_args", True)
        self.resilient_parsing = False
        self._sources = {}
        self._close_callbacks = []
        self._env_parts = []
