        if parent is not None:
            self.default_map = self._nested_map(parent, command)

    @staticmethod
    def _nested_map(parent, command):
        dm = parent.default_map
        if isinstance(dm, dict):
            return dm.get(command.name)
        return None

    # --- context manager protocol -------------------------------------
    def __enter__(self):
        _stack().append(self)
        return self

    def __exit__(self, exc_type, exc, tb):
        stack = _stack()
        if stack and stack[-1] is self:
            stack.pop()
        return False

    # --- resources -----------------------------------------------------
    def call_on_close(self, fn):
        self._close_callbacks.append(fn)

    def close(self):
        callbacks, self._close_callbacks = self._close_callbacks, []
        for fn in reversed(callbacks):
            try:
                fn()
            except Exception:
                pass

    def with_resource(self, cm):
        value = cm.__enter__()
        self.call_on_close(lambda: cm.__exit__(None, None, None))
        return value

    # --- control -------------------------------------------------------
    def exit(self, code=0):
        raise Exit(code)

    def abort(self):
        raise Abort()

    # --- help ----------------------------------------------------------
    def get_help(self):
        from .formatting import format_help

        return format_help(self.command, self)

    def get_usage(self):
        from .formatting import format_usage

        return format_usage(self.command, self)

