import os

from . import types as _types
from .core import OMITTED, Argument, Option, ParameterSource
from .exceptions import BadParameter, MissingParameter, NoSuchOption, UsageError

_BOOL_TRUE = {"true", "1", "yes", "on", "t", "y"}
_BOOL_FALSE = {"false", "0", "no", "off", "f", "n"}
_PROMPT = object()  # option flag given without a value


def _norm(ctx, name):
    func = ctx.token_normalize_func
    return func(name) if func else name


def _build_lookup(command, ctx):
    """Map each option name to (param, mode, value). # spec: N-000175..N-000193"""
    lookup = {}
    for p in command.params:
        if not isinstance(p, Option):
            continue
        if p.count:
            for n in p.opts:
                lookup[_norm(ctx, n)] = (p, "flag", 1)
            continue
        if p.is_flag:
            for n in p.opts:
                lookup[_norm(ctx, n)] = (p, "flag", p.flag_value if not p.secondary_opts else True)
            for n in p.secondary_opts:
                lookup[_norm(ctx, n)] = (p, "flag", False)
            continue
        mode = "optval" if p.flag_value is not None else "value"
        for n in p.opts:
            lookup[_norm(ctx, n)] = (p, mode, None)
    return lookup


