    def __init__(self):
        self.occurrences = {}  # name -> [(index, value)]
        self.arg_values = {}  # name -> raw token(s) or OMITTED
        self.leftover = []


def parse_tokens(command, ctx, args):
    """Split tokens into option occurrences, argument values, and leftovers."""
    from .commands import Group

    lookup = _build_lookup(command, ctx)
    prefixes = {n[0] for n in lookup} | {"-"}
    result = ParseResult()
    positional = []
    interspersed = getattr(command, "interspersed_args", True)
    args = list(args)
    n = len(args)
    i = 0
    stop = False

    def record(p, idx, value):
        result.occurrences.setdefault(p.name, []).append((idx, value))

    def take_value(p, idx, nxt, inline):
        """Consume the value tokens of a value-taking option. Returns next index."""
        if inline is not None:
            record(p, idx, inline if p.nargs == 1 else tuple([inline]))
