            return name[: -len(dashed)]
    return name


def _default_prog_name():
    argv0 = sys.argv[0] if sys.argv and sys.argv[0] else "main"
    base = os.path.basename(argv0)
    if base.endswith(".py"):
        base = base[:-3]
