        if catch_exceptions is None:
            catch_exceptions = self.catch_exceptions
        if args is None:
            args = []
        elif isinstance(args, str):
            import shlex

            args = shlex.split(args)
        standalone = extra.pop("standalone_mode", True)
        prog_name = extra.pop("prog_name", None) or "cli"
        exit_code = 0
        exception = None
        with self.isolation(input=input, env=env, color=color) as (out_sink, err_sink, combined):
            settings = dict(extra)
            settings["color"] = color
            try:
                cli.main(args=list(args), prog_name=prog_name, standalone_mode=standalone,
